function ChoiceDropdown({label,value,options,onChange}:{label:string;value:string;options:string[];onChange:(v:string)=>void}){const [open,setOpen]=useState(false);return <View style={{marginTop:10}}><Text style={S.fieldLabel}>{label}</Text><Pressable onPress={()=>setOpen(true)} style={[S.field,{minHeight:48,justifyContent:'center',flexDirection:'row',alignItems:'center'}]}><Text style={{flex:1,color:'#19345B',fontWeight:'800'}}>{value}</Text><Text style={{color:'#176CFF',fontSize:18}}>▾</Text></Pressable><Modal visible={open} transparent animationType="fade" onRequestClose={()=>setOpen(false)}><Pressable onPress={()=>setOpen(false)} style={{flex:1,backgroundColor:'rgba(7,17,45,.55)',justifyContent:'center',padding:24}}><View style={{backgroundColor:'#FFFFFF',borderRadius:22,padding:16,maxHeight:'75%',borderWidth:2,borderColor:'#8AD9FF'}}><Text style={{fontSize:16,fontWeight:'900',color:'#15274A',marginBottom:10}}>{label}</Text><ScrollView>{options.map(o=><Pressable key={o} onPress={()=>{onChange(o);setOpen(false)}} style={{padding:14,marginBottom:6,borderRadius:12,backgroundColor:o===value?'#DCEBFF':'#F3F7FF'}}><Text style={{fontWeight:'800',color:'#19345B'}}>{o}</Text></Pressable>)}</ScrollView><Pressable onPress={()=>setOpen(false)} style={{padding:12,alignItems:'center'}}><Text style={{fontWeight:'900',color:'#176CFF'}}>CLOSE</Text></Pressable></View></Pressable></Modal></View>}
